window.onload=wrapTable(),convertFootnotesToSidenotes();function wrapTable(){const e=document.querySelectorAll("table");e.forEach(e=>{const t=document.createElement("div");t.className="table-wrapper",e.parentElement.replaceChild(t,e),t.appendChild(e)})}function convertFootnotesToSidenotes(){if(window.__sidenotesInitialized)return;window.__sidenotesInitialized=!0,document.querySelectorAll("sup.footnote-ref").forEach(e=>{const n=e.querySelector('a[href^="#fn:"]');if(!n)return;const o=document.querySelector(n.getAttribute("href"));if(!o)return;const i=o.cloneNode(!0);i.querySelectorAll("a.footnote-backref").forEach(e=>e.remove());const t=document.createElement("span");t.className="sidenote";const s=document.createElement("span");s.className="sidenote-number",s.textContent=n.textContent,t.appendChild(s),t.insertAdjacentHTML("beforeend",i.innerHTML),e.insertAdjacentElement("afterend",t)})}